CREATE OR REPLACE FUNCTION public.delete_my_account_and_data()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_id uuid := auth.uid();
  target_email text := public.life_pilot_user_email();
begin
  if target_id is null or target_email = '' then
    raise exception 'authentication_required';
  end if;

  perform public.cleanup_subscription_data(null, 'all');

  delete from public.feedback
   where lower(trim(created_by)) = target_email;
  delete from public.dashboard_setting
   where lower(trim(account)) = target_email;
  delete from public.user_module
   where lower(trim(account)) = target_email;
  delete from public.recommended_events_favor
   where lower(trim(account)) = target_email;
  delete from public.recommended_events_stat
   where lower(trim(account)) = target_email;
  delete from public.legal_consents where user_id = target_id;
  delete from public.user_subscription_entitlements where user_id = target_id;
  delete from public.subscription_payment_events where user_id = target_id;
  delete from public.subscription_cleanup_audit where user_id = target_id;
  delete from public.user_subscriptions where user_id = target_id;
  delete from auth.users where id = target_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_vendor_content_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := public.life_pilot_user_email();
  v_entitlement jsonb;
  v_days integer;
  v_result jsonb;
begin
  if auth.uid() is null or v_email = '' then
    raise exception 'authentication_required';
  end if;

  v_entitlement := public.life_pilot_vendor_entitlement(auth.uid(), v_email);
  v_days := greatest(
    coalesce((v_entitlement ->> 'analytics_days')::integer, 30),
    1
  );

  with owned_content as (
    select e.id::text as content_id
    from public.recommended_events e
    where lower(trim(e.account)) = v_email
    union
    select a.id::text
    from public.recommended_attractions a
    where lower(trim(a.account)) = v_email
  ), relevant_stats as (
    select s.*
    from public.recommended_events_stat s
    join owned_content c on c.content_id = s.event_id
    where s.create_date >= now() - make_interval(days => v_days)
  )
  select jsonb_build_object(
    'analytics_days', v_days,
    'page_views', count(*) filter (where typename = 'page_views'),
    'card_clicks', count(*) filter (where typename = 'card_clicks'),
    'registration_clicks',
      count(*) filter (where typename = 'registration_clicks'),
    'saves', count(*) filter (where typename = 'saves'),
    'likes', count(*) filter (where typename = 'like_counts'),
    'dislikes', count(*) filter (where typename = 'dislike_counts')
  ) into v_result
  from relevant_stats;

  return coalesce(v_result, jsonb_build_object(
    'analytics_days', v_days,
    'page_views', 0,
    'card_clicks', 0,
    'registration_clicks', 0,
    'saves', 0,
    'likes', 0,
    'dislikes', 0
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.life_pilot_cached_map_coordinates(p_table_name text, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e record; v_result jsonb; v_visible text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_table_name is null or p_table_name not in
      ('calendar_events','memory_trace','recommended_events','recommended_attractions')
      or nullif(trim(p_event_id),'') is null or length(p_event_id) > 200 then
    raise exception 'Invalid event target' using errcode = '22023';
  end if;
  -- Same visibility as the original server: private calendars/memories owner only.
  v_visible := 'lower(account) = public.life_pilot_user_email()';
  if p_table_name in ('recommended_events','recommended_attractions') then
    v_visible := '(' || v_visible ||
      ' or coalesce(is_approved,false) or public.life_pilot_is_admin())';
  end if;
  execute format('select id,country,city,location,map_lat,map_lng from public.%I
    where id::text = $1 and (%s) for update',p_table_name,v_visible)
    into e using p_event_id;
  if e.id is null then
    raise exception 'Event not found or not visible' using errcode = '42501';
  end if;
  if e.map_lat is not null and e.map_lng is not null then
    return jsonb_build_object('lat',e.map_lat,'lng',e.map_lng);
  end if;
  if nullif(trim(e.city),'') is null and nullif(trim(e.location),'') is null then
    return '{}'::jsonb;
  end if;
  v_result := public.life_pilot_geocode_cache_result(concat_ws(', ',
    nullif(trim(e.location),''),nullif(trim(e.city),''),
    coalesce(nullif(upper(trim(e.country)),''),'TW')));
  if v_result ? 'lat' and e.map_lat is null and e.map_lng is null then
    -- Coordinates come ONLY from the server-owned cache, never client input.
    -- The row lock also prevents saving coordinates for an outdated address.
    execute format('update public.%I set map_lat=$1,map_lng=$2 where id::text=$3',
      p_table_name) using (v_result->>'lat')::float8,
      (v_result->>'lng')::float8,p_event_id;
  end if;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.list_my_shared_ledger_overview(p_kind text, p_limit integer, p_offset integer, p_month_start timestamp with time zone, p_month_end timestamp with time zone, p_day_start timestamp with time zone, p_day_end timestamp with time zone)
 RETURNS TABLE(share_id uuid, kind text, account_id text, account_name text, totals jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  entry record;
begin
  for entry in select * from public.list_my_shared_ledgers_by_kind(p_kind, p_limit, p_offset)
  loop
    share_id := entry.share_id;
    kind := entry.kind;
    account_id := entry.account_id;
    account_name := entry.account_name;
    begin
      totals := public.get_my_shared_ledger_totals(
        share_id, p_month_start, p_month_end, p_day_start, p_day_end);
    exception when insufficient_privilege then
      totals := null;
    end;
    return next;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_point_record_detail(p_detail_id uuid, p_new_value bigint, p_new_description text, p_new_date timestamp with time zone, p_new_primary_category text, p_new_group text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_account_id uuid;
  v_old_value bigint;
  v_type text;
begin
  select account_id, value, type
    into v_account_id, v_old_value, v_type
  from public.point_record_detail
  where id = p_detail_id
  for update;

  if not found then
    raise exception 'Point record detail not found';
  end if;
  if v_type <> 'points' then
    raise exception 'Only point records can be edited';
  end if;

  update public.point_record_account
  set points = coalesce(points, 0) - coalesce(v_old_value, 0) + p_new_value
  where id = v_account_id;

  update public.point_record_detail
  set value = p_new_value,
      description = p_new_description,
      date = p_new_date,
      primary_category = p_new_primary_category,
      "group" = coalesce(p_new_group, '')
  where id = p_detail_id;
end;
$function$
